-- ─────────────────────────────────────────────────────────────────
-- 3. CATEGORÍAS DE PRODUCTO  (277 categorías derivadas del nombre)
-- ─────────────────────────────────────────────────────────────────
PRINT N'Migrando categorías de productos...';

CREATE TABLE #CatMap (Nombre NVARCHAR(100) PRIMARY KEY, CategoriaId UNIQUEIDENTIFIER);

IF NOT EXISTS (SELECT 1 FROM OPT_ProductoCategoria WHERE TenantId=@TenantId AND Nombre=N'0Ctavia' AND IsDeleted=0)
BEGIN
    DECLARE @v_0Ctavia UNIQUEIDENTIFIER = NEWID();
    INSERT INTO OPT_ProductoCategoria (CategoriaId,TenantId,Nombre,CreatedBy)
    VALUES (@v_0Ctavia,@TenantId,N'0Ctavia',@CreatedBy);
    INSERT INTO #CatMap VALUES (N'0Ctavia', @v_0Ctavia);
END
ELSE
    INSERT INTO #CatMap SELECT N'0Ctavia', CategoriaId FROM OPT_ProductoCategoria
    WHERE TenantId=@TenantId AND Nombre=N'0Ctavia' AND IsDeleted=0;

