);

DROP TABLE #CatMap;

-- ─────────────────────────────────────────────────────────────────
-- RESUMEN
-- ─────────────────────────────────────────────────────────────────
PRINT N'';
PRINT N'=== RESUMEN DE MIGRACIÓN ===';
PRINT N'Clientes Empresa : ' + CAST((SELECT COUNT(*) FROM OPT_Cliente WHERE TenantId=@TenantId AND TipoCliente=N'Empresa' AND IsDeleted=0) AS NVARCHAR);
PRINT N'Clientes Persona : ' + CAST((SELECT COUNT(*) FROM OPT_Cliente WHERE TenantId=@TenantId AND TipoCliente=N'Persona' AND IsDeleted=0) AS NVARCHAR);
PRINT N'Categorías       : ' + CAST((SELECT COUNT(*) FROM OPT_ProductoCategoria WHERE TenantId=@TenantId AND IsDeleted=0) AS NVARCHAR);
PRINT N'Productos        : ' + CAST((SELECT COUNT(*) FROM OPT_Producto WHERE TenantId=@TenantId AND IsDeleted=0) AS NVARCHAR);

COMMIT TRANSACTION;
PRINT N'Migración completada exitosamente.';

END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    PRINT N'ERROR en línea ' + CAST(ERROR_LINE() AS NVARCHAR) + ': ' + ERROR_MESSAGE();
    THROW;
END CATCH;
